import * as D from './domain.js';
import {openDB,persist} from './db.js';
import {fetchCBR} from './currency.js';
import {recognitionAvailable,startRecognition} from './voice.js';
import {backupSnapshot,backupSummary,encryptBackup,decryptBackup} from './backup.js';
const $=s=>document.querySelector(s),app=$('#app'),sheet=$('#sheet');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={stack:'M4 6h16M3 11h18l-2 9H5zM7 2h10',home:'M3 10l9-7 9 7M5 9v12h5v-7h4v7h5V9',history:'M3 5v5h5M3 10a9 9 0 1 1 1 8M12 7v6l4 2',chart:'M4 20V10M10 20V4M16 20v-8M22 20H2',dots:'M4 12h1M11 12h1M18 12h1',plus:'M12 5v14M5 12h14',arrow:'M4 8h16l-4-4M20 16H4l4 4',wallet:'M3 6h18v14H3zM3 6V3h15v3M16 11h5v5h-5z',basket:'M3 9h18l-2 11H5zM7 9l3-6M17 9l-3-6M9 13v3M15 13v3',cup:'M4 5h13v10a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM17 7h3v6h-3M3 22h16',car:'M4 10l2-6h12l2 6M3 10h18v8H3zM6 18v3M18 18v3M6 13h2M16 13h2',bag:'M4 7h16l1 14H3zM8 7V5a4 4 0 0 1 8 0v2',phone:'M7 2h10v20H7zM10 18h4',heart:'M12 21S1 14 3 7c2-5 7-4 9 0 2-4 7-5 9 0 2 7-9 14-9 14z',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',close:'M6 6l12 12M18 6L6 18',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0M12 10v4',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',chevron:'M9 5l7 7-7 7'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.dots}"/></svg>`;
const money=(n,c='RUB')=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:c,maximumFractionDigits:n%100?2:0}).format(n/100);
const val=n=>(n/100).toFixed(2),monthNow=()=>D.today().slice(0,7),sum=a=>a.reduce((x,y)=>x+y,0);
let state,view='home',month=monthNow(),search='',filter='all',limit=60,locked=false,busy=false,toastTimer,lastActivity=Date.now(),pendingImport=null,importKind='',draft=null,splitDraft=[],pendingURL=location.hash.slice(1);
const bc='BroadcastChannel'in window?new BroadcastChannel('stack-state'):null;
bc?.addEventListener('message',()=>toast('Данные изменены в другой вкладке. Перезагрузите Stack.'));
const active=()=>state.accounts.filter(a=>!a.archived);
const cat=id=>state.categories.find(c=>c.id===id);
const acc=id=>state.accounts.find(a=>a.id===id);
function toast(text,undo){clearTimeout(toastTimer);const t=$('#toast');t.innerHTML=`<span>${e(text)}</span>${undo?'<button id="undo">Отменить</button>':''}`;t.className='visible';if(undo)$('#undo').onclick=undo;toastTimer=setTimeout(()=>t.className='',undo?5500:4500);}
async function change(fn){if(busy)throw Error('Дождитесь сохранения');busy=true;try{const next=structuredClone(state);fn(next);D.validateBackup(next);await persist(next,state.revision);state=next;bc?.postMessage('changed');return true;}finally{busy=false;}}
function theme(){const t=state.settings.theme;const mode=t==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):t;document.documentElement.dataset.theme=mode;document.querySelector('meta[name=theme-color]')?.setAttribute('content',mode==='dark'?'#101114':'#f2f3f7');}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>state&&theme());
function modal(title,body,submit){sheet.innerHTML=`<div class="sheet-head"><h2>${e(title)}</h2><button type="button" data-close aria-label="Закрыть">${icon('close')}</button></div>${submit?'<form id="form">':''}${body}${submit?'<p id="form-error" class="error" role="alert"></p></form>':''}`;if(!sheet.open)sheet.showModal();if(submit)$('#form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;try{if(button)button.disabled=true;await submit(new FormData(event.target));}catch(err){const el=$('#form-error');if(el)el.textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}};}
function close(){try{currentRecognition?.abort();}catch{}currentRecognition=null;sheet.close();draft=null;}
const field=(label,name,value='',type='text',extra='')=>`<label for="f-${name}">${e(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}>`;
const options=(items,selected)=>items.map(([id,label])=>`<option value="${e(id)}" ${id===selected?'selected':''}>${e(label)}</option>`).join('');
const select=(label,name,items,selected)=>`<label for="f-${name}">${e(label)}</label><select name="${name}" id="f-${name}">${options(items,selected)}</select>`;
const aopts=(include)=>state.accounts.filter(a=>!a.archived||include?.includes(a.id)).map(a=>[a.id,`${a.name} · ${a.currency}${a.archived?' · архив':''}`]);
const copts=(include)=>state.categories.filter(c=>!c.hidden||c.id===include).map(c=>[c.id,c.name]);
const saveButton=(text='Сохранить')=>`<button class="primary" type="submit">${text}</button>`;
const empty=(title,text,action,label)=>`<div class="empty">${icon('stack')}<h3>${e(title)}</h3><p>${e(text)}</p>${action?`<button class="primary" data-action="${action}">${label}</button>`:''}</div>`;
function nav(){return `<nav aria-label="Основная навигация">${[['home','home','Главная'],['history','history','История'],['add','plus','Добавить'],['analytics','chart','Аналитика'],['more','dots','Ещё']].map(([id,i,label])=>`<button data-nav="${id}" class="${id==='add'?'add':view===id?'active':''}" aria-label="${label}" ${view===id?'aria-current="page"':''}>${icon(i)}${id==='add'?'':`<span>${label}</span>`}</button>`).join('')}</nav>`;}
function render(){theme();if(locked){renderLock();return;}if(!state.accounts.length){onboard();return;}app.innerHTML=`<main class="container"><header><div class="brand">${icon('stack')}Stack<span class="subtitle">личные финансы</span></div><button class="plain" data-action="settings" aria-label="Настройки">${icon('dots')}</button></header>${({home,history,analytics,more})[view]()}</main>${nav()}`;}
function monthPicker(){return `<div class="month"><input type="month" id="month" aria-label="Месяц отчёта" value="${month}" min="2000-01" max="2100-12"></div>`;}
function txList(items){return items.length?`<div class="list">${items.map(t=>{const c=cat(t.categoryId),transfer=t.type==='transfer',a=acc(t.splits[0].accountId);return `<button class="list-item" data-action="editTx" data-id="${e(t.id)}"><span class="badge">${icon(transfer?'arrow':c?.icon)}</span><span class="grow"><strong>${e(t.note|| (transfer?'Перевод':c?.name))}</strong><small>${e(t.date.split('-').reverse().join('.'))} · ${e(a.name)}${t.splits.length>1&&!transfer?' + сплит':''}</small></span><span class="money ${t.type==='income'?'positive':''}">${transfer?'↔ ':t.type==='expense'?'−':'+'}${money(D.amount(t),transfer?acc(t.splits[1].accountId).currency:a.currency)}</span></button>`;}).join('')}</div>`:empty('Пока ни одной операции','Добавьте первую трату — баланс и лимит пересчитаются.','addTx','Добавить операцию');}
function home(){const current=monthNow(),st=D.stats(state,current),due=D.unpaid(state,current).filter(r=>{const d=D.dueDate(r,current);return (new Date(d+'T12:00:00')-new Date(D.today()+'T12:00:00'))/86400000<=r.before;});const total=D.total(state),free=D.free(state,current);return `<div class="row between space"><div><div class="eyebrow">Всё под контролем</div><h1 style="margin-bottom:0">Ваши деньги.</h1></div><span class="pill">${icon('shield')} На устройстве</span></div>${due.map(r=>`<div class="banner"><div><strong>${e(r.name)}</strong> · ${money(r.amount,acc(r.accountId).currency)}<br><span class="muted">К оплате ${D.dueDate(r,current).split('-').reverse().join('.')}</span></div><button class="small primary" data-action="pay" data-id="${e(r.id)}">Оплатить</button></div>`).join('')}${state.settings.backupReminderDays!==0&&(!state.settings.lastBackup||Date.now()-Date.parse(state.settings.lastBackup)>(state.settings.backupReminderDays||7)*864e5)?`<div class="banner"><span>Сохраните копию, чтобы не потерять записи при очистке браузера.</span><button class="plain small" data-action="backup">Сохранить</button></div>`:''}<div class="grid"><section class="card hero"><div><div class="eyebrow">Общий баланс · ₽</div><div class="big">${money(total)}</div><div class="muted">Свободно ${money(free)}</div></div><div class="row between"><span class="pill">${state.accounts.length} ${state.accounts.length===1?'счёт':'счета'}</span><button class="small row" data-action="transfer">${icon('arrow')} Перевести</button></div></section><section class="card"><div class="row between"><span class="eyebrow">Можно сегодня</span>${icon('sun')}</div><div class="big gap ${st.leftToday<0?'negative':''}">${money(Math.max(0,st.leftToday))}</div><p class="muted">${st.budget[1]?`Из лимита ${money(st.limit)} · потрачено ${money(st.todaySpent)}`:'Задайте бюджет повседневных расходов'}</p><div class="progress"><span style="width:${st.limit>0?Math.min(100,st.todaySpent/st.limit*100):0}%"></span></div><div class="row between help"><span>${st.leftToday<0?`Превышение ${money(-st.leftToday)}`:`До конца месяца ${st.days} дн.`}</span><button class="plain small" data-action="budgets">Бюджеты</button></div></section></div><div class="section-head"><h2>Мои счета</h2><button class="plain small" data-action="account">+ Счёт</button></div><div class="account-grid">${active().map(a=>`<button class="account" data-action="account" data-id="${e(a.id)}"><span class="account-top">${e(a.name)}${icon(a.type==='cash'?'wallet':'stack')}</span><strong class="${D.balance(state,a.id)<0?'negative':''}">${money(D.balance(state,a.id),a.currency)}</strong><small>${({debit:'Дебетовый',cash:'Наличные',credit:'Кредитный',savings:'Накопительный'})[a.type]}</small></button>`).join('')}</div><div class="section-head"><h2>Быстрая запись</h2><button class="plain small" data-action="template">+ Шаблон</button></div><div class="quick"><button data-action="smart">✦ Из текста / QR</button><button data-action="voice" class="voice-quick">🎙 Голосом</button>${state.templates.map(t=>`<button data-action="useTemplate" data-id="${e(t.id)}">${e(t.name)} · ${money(t.amount,acc(t.accountId).currency)}</button>`).join('')}</div><div class="metric-grid gap"><button class="card" data-action="goals" style="text-align:left"><span class="muted">Цели</span><strong>${money(sum(state.goals.map(g=>g.saved)))}</strong><span class="help">${state.goals.length} целей · зарезервировано</span></button><button class="card" data-action="loans" style="text-align:left"><span class="muted">Мне должны</span><strong>${money(sum(state.loans.filter(l=>l.direction==='owed').map(l=>l.remaining)))}</strong><span class="help">Мои долги ${money(sum(state.loans.filter(l=>l.direction==='owe').map(l=>l.remaining)))}</span></button></div><div class="section-head"><h2>Последние операции</h2><button class="plain small" data-nav="history">Все</button></div>${txList(state.transactions.filter(t=>!t.deleted).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created)).slice(0,5))}<p class="help">Свободно = баланс − резерв целей − неоплаченные платежи месяца. Валютные суммы пересчитываются по ручному курсу из настроек.</p>`;}
function history(){const items=state.transactions.filter(t=>!t.deleted&&t.date.startsWith(month)&&(filter==='all'||t.splits.some(p=>p.accountId===filter))&&`${t.note} ${cat(t.categoryId)?.name}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created));return `<div class="row between space"><h1 style="margin:0">История</h1>${monthPicker()}</div><div class="toolbar"><input id="search" placeholder="Поиск по заметке и категории" aria-label="Поиск операций" value="${e(search)}"><select id="account-filter" aria-label="Фильтр по счету">${options([['all','Все счета'],...state.accounts.map(a=>[a.id,a.name])],filter)}</select></div>${txList(items.slice(0,limit))}${items.length>limit?'<button class="gap" data-action="moreHistory">Показать ещё</button>':''}<p class="help">${items.length} операций · нажмите на запись, чтобы изменить её.</p>`;}
function analytics(){const st=D.stats(state,month),days=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate(),daily=Array(days).fill(0);for(const t of state.transactions.filter(t=>!t.deleted&&t.type==='expense'&&t.date.startsWith(month)))daily[Number(t.date.slice(8))-1]+=D.txRub(state,t);const max=Math.max(1,...daily);return `<div class="row between space"><h1 style="margin:0">Итог месяца</h1>${monthPicker()}</div><div class="metric-grid"><div class="card"><span class="muted">Доходы</span><strong class="positive">${money(st.income)}</strong></div><div class="card"><span class="muted">Расходы</span><strong>${money(st.expense)}</strong></div></div><div class="card gap"><div class="row between"><h2>Движение за месяц</h2><span class="pill ${st.income-st.expense<0?'negative':'positive'}">${money(st.income-st.expense)}</span></div><div class="chart" role="img" aria-label="Расходы по дням">${daily.map((n,i)=>`<div class="bar" style="height:${Math.max(2,n/max*100)}%;opacity:${n?1:.15}" title="${i+1}: ${money(n)}"></div>`).join('')}</div><div class="chart-labels"><span>1 ${month}</span><span>${days} ${month}</span></div></div><div class="grid gap"><div class="card"><h2>План и факт</h2>${D.sections.map((name,i)=>`<div class="gap"><div class="row between"><span>${name}</span><strong>${money(st.spent[i])}</strong></div><div class="progress"><span style="width:${st.budget[i]?Math.min(100,st.spent[i]/st.budget[i]*100):0}%;background:${st.spent[i]>st.budget[i]?'var(--red)':'var(--blue)'}"></span></div><div class="help">Бюджет ${money(st.budget[i])} · остаток ${money(st.budget[i]-st.spent[i])}</div></div>`).join('')}<button class="plain gap" data-action="budgets">Изменить бюджет</button></div><div class="card"><h2>По категориям</h2>${Object.entries(st.cats).sort((a,b)=>b[1]-a[1]).map(([id,n])=>`<div class="gap"><div class="row between"><span>${e(cat(id)?.name)}</span><strong>${money(n)}</strong></div><div class="progress"><span style="width:${n/Math.max(1,st.expense)*100}%"></span></div></div>`).join('')||'<p class="muted gap">Расходов ещё нет.</p>'}</div></div><div class="section-head"><h2>Остатки по счетам сейчас</h2></div><div class="list">${state.accounts.map(a=>`<div class="list-item"><span class="grow">${e(a.name)}${a.archived?' · архив':''}</span><strong>${money(D.balance(state,a.id),a.currency)}</strong></div>`).join('')}</div><p class="help">Переводы исключены из доходов и расходов. Цели — резерв, а не расход. Возврат долга отражается в денежном потоке.</p>`;}
function more(){return `<div class="eyebrow">Ваш Stack</div><h1>Всё остальное</h1><div class="list">${[['recurring','calendar','Платежи','Регулярные расходы и календарь'],['goals','target','Цели','Откладывайте на важное'],['loans','wallet','Долги и общие чеки','Кто, кому и сколько'],['templates','plus','Шаблоны','Быстрая запись привычных расходов'],['categories','basket','Категории','Настройте учёт под себя'],['accounts','stack','Счета','Управление и архив'],['import','download','Импорт данных','Stack, Money Radar и CSV'],['shortcuts','arrow','Команды и умный ввод','Текст, SMS и QR чека'],['settings','dots','Настройки','Тема, курсы, PIN и резервные копии']].map(([action,i,title,sub])=>`<button class="list-item" data-action="${action}"><span class="badge">${icon(i)}</span><span class="grow"><strong>${title}</strong><small>${sub}</small></span>${icon('chevron')}</button>`).join('')}</div><p class="help gap">Stack 1.1 · без аккаунта и рекламы.<br>Данные этого устройства не синхронизируются с другими. Периодически сохраняйте JSON-копию.</p>`;}
function onboard(){app.innerHTML=`<main class="container"><section class="onboard"><div class="mark">${icon('stack')}</div><div class="eyebrow">Финансы в своём ритме</div><h1>Меньше шума.<br>Больше ясности.</h1><p class="muted">Счета, повседневные траты и планы — в одной аккуратной стопке.</p><div class="card gap"><div class="row">${icon('shield')}<strong>Только на вашем устройстве</strong></div><p class="help">Без регистрации и облака. Начните со счёта и текущего остатка. Затем задайте месячные бюджеты.</p></div><button class="primary" data-action="account">Создать первый счёт</button><button class="plain" data-action="import">У меня есть резервная копия</button></section></main>`;}
function accountForm(id){const old=state.accounts.find(a=>a.id===id),a=old||{name:'',type:'debit',currency:'RUB',initial:0};modal(old?'Настройки счёта':'Новый счёт',field('Название','name',a.name,'text','required maxlength="60" placeholder="Например, Основная карта"')+select('Тип','type',[['debit','Дебетовый'],['cash','Наличные'],['credit','Кредитный'],['savings','Накопительный']],a.type)+select('Валюта','currency',[['RUB','Рубли · ₽'],['USD','Доллары · $'],['EUR','Евро · €']],a.currency)+field('Начальный остаток (может быть отрицательным)','initial',val(a.initial),'text','inputmode="decimal" required')+'<p class="help">Это остаток до первой записанной операции. Изменение пересчитает весь баланс. Валюту счёта с историей менять нельзя.</p>'+saveButton()+(old?`<button class="plain danger gap" type="button" data-action="archive" data-id="${e(id)}">${a.archived?'Вернуть из архива':'Архивировать счёт'}</button>`:''),async f=>{const currency=f.get('currency');if(old&&currency!==old.currency&&state.transactions.some(t=>t.splits.some(p=>p.accountId===id)))throw Error('Сначала создайте отдельный счёт в нужной валюте');const initial=D.cents(f.get('initial')),name=f.get('name').trim();if(!name)throw Error('Введите название');const first=!state.accounts.length;await change(s=>{const item={...a,id:id||D.uid(),name,type:f.get('type'),currency,initial,archived:a.archived||false};if(old)s.accounts[s.accounts.findIndex(x=>x.id===id)]=item;else s.accounts.push(item);});close();render();if(first)budgetForm();});}
function budgetForm(){const m=view==='home'?monthNow():month,b=state.budgets[m]||[0,0,0];modal('Бюджет на месяц',field('Месяц','month',m,'month','required min="2000-01" max="2100-12"')+D.sections.map((n,i)=>field(n+' · ₽','b'+i,val(b[i]),'text','inputmode="decimal" required')).join('')+'<p class="help">Дневной лимит использует только «Повседневные». Каждый месяц имеет отдельный бюджет. Будущие доходы в лимит не включаются.</p>'+saveButton(),async f=>{const b=[0,1,2].map(i=>D.cents(f.get('b'+i)));if(b.some(n=>n<0))throw Error('Бюджеты не могут быть отрицательными');await change(s=>s.budgets[f.get('month')]=b);close();render();});}
function txForm(id,seed={}){if(!active().length&&!id){accountForm();return;}const old=state.transactions.find(t=>t.id===id);draft=old?structuredClone(old):{id:D.uid(),type:seed.type||'expense',date:seed.date||D.today(),categoryId:seed.categoryId||state.categories.find(c=>!c.hidden)?.id,note:seed.note||'',created:new Date().toISOString(),...seed};splitDraft=old?old.splits.map(p=>({accountId:p.accountId,value:val(Math.abs(p.amount))})):[{accountId:seed.accountId||active()[0].id,value:seed.amount?val(seed.amount):''}];const t=draft;modal(old?'Изменить операцию':t.type==='transfer'?'Перевод':'Новая операция',`${t.type!=='transfer'?select('Тип','type',[['expense','Расход'],['income','Доход']],t.type):''}${field('Сумма'+(t.type==='transfer'?' списания':''),'amount',old?val(t.type==='transfer'?Math.abs(t.splits[0].amount):D.amount(t)):seed.amount?val(seed.amount):'','text','inputmode="decimal" required placeholder="0,00"')}${t.type==='transfer'?select('Откуда','from',aopts(old?.splits.map(p=>p.accountId)),old?.splits[0].accountId||active()[0]?.id)+select('Куда','to',aopts(old?.splits.map(p=>p.accountId)),old?.splits[1].accountId||active()[1]?.id)+field('Зачислить (только для разных валют)','received',old?val(t.splits[1].amount):'','text','inputmode="decimal" placeholder="Для одной валюты заполнится автоматически"'):`${select('Категория','categoryId',copts(t.categoryId),t.categoryId)}<label>Оплата со счетов</label><div id="splits"></div><div class="row between"><button type="button" class="plain small" data-action="addSplit">+ Ещё счёт</button><button type="button" class="plain small" data-action="equalSplit">Поровну</button></div><p id="split-diff" class="help"></p>`}${field('Дата','date',t.date,'date','required')}${field('Заметка / магазин','note',t.note,'text','maxlength="500"')}${t.type==='expense'&&!old?'<details class="gap"><summary>Общий чек: мне должны часть суммы</summary>'+field('Имя должника','debtor','','text','maxlength="80"')+field('Его доля, ₽','debtAmount','','text','inputmode="decimal"')+'<p class="help">Для рублёвого чека. Расход сохраняется целиком; доля друга создаёт запись «мне должны».</p></details>':''}${saveButton(old?'Сохранить изменения':'Добавить операцию')}${old?`<button type="button" class="plain danger gap" data-action="deleteTx" data-id="${e(id)}">Удалить операцию</button>`:''}`,async f=>{const n=D.cents(f.get('amount'));if(n<=0)throw Error('Сумма должна быть больше нуля');let splits;if(t.type==='transfer'){const from=f.get('from'),to=f.get('to');if(from===to)throw Error('Выберите разные счета');const other=acc(from).currency!==acc(to).currency,received=other?D.cents(f.get('received')):n;if(received<=0)throw Error('Укажите сумму зачисления');splits=[{accountId:from,amount:-n},{accountId:to,amount:received}];}else{captureSplits();splits=splitDraft.map(p=>({accountId:p.accountId,amount:(f.get('type')==='expense'?-1:1)*(splitDraft.length===1?n:D.cents(p.value))}));if(sum(splits.map(p=>Math.abs(p.amount)))!==n)throw Error('Сумма сплитов не совпадает с общей суммой');}
 const tx={...t,type:t.type==='transfer'?'transfer':f.get('type'),splits,date:f.get('date'),note:f.get('note').trim(),categoryId:t.type==='transfer'?undefined:f.get('categoryId'),updated:new Date().toISOString()};D.validateTx(state,tx);
 const debtor=f.get('debtor')?.trim(),debtValue=f.get('debtAmount')?.trim();let debt=0;if(debtor||debtValue){if(tx.type!=='expense'||splits.some(p=>acc(p.accountId).currency!=='RUB'))throw Error('Общий чек доступен для расходов в рублях');debt=D.cents(debtValue);if(!debtor||debt<=0||debt>n)throw Error('Укажите имя и долю не больше чека');}
 await change(s=>{if(old)s.transactions[s.transactions.findIndex(x=>x.id===id)]=tx;else{s.transactions.push(tx);if(debt)s.loans.push({id:D.uid(),name:debtor,remaining:debt,original:debt,direction:'owed',transactionId:tx.id,date:tx.date});}});close();render();toast('Операция сохранена');});if(t.type!=='transfer')renderSplits();}
function captureSplits(){if(!$('#splits'))return;splitDraft=[...sheet.querySelectorAll('.split-row')].map(r=>({accountId:r.querySelector('select').value,value:r.querySelector('input').value}));}
function renderSplits(){const total=$('#f-amount').value;$('#splits').innerHTML=splitDraft.map((p,i)=>`<div class="split-row"><select aria-label="Счёт ${i+1}">${options(aopts([p.accountId]),p.accountId)}</select><input aria-label="Сумма со счёта ${i+1}" inputmode="decimal" value="${e(splitDraft.length===1?total:p.value)}" ${splitDraft.length===1?'disabled':''}><button type="button" data-remove-split="${i}" aria-label="Убрать счёт" ${splitDraft.length===1?'disabled':''}>×</button></div>`).join('');splitDiff();}
function splitDiff(){try{const n=D.cents($('#f-amount').value||'0');if(splitDraft.length===1){$('#splits input').value=$('#f-amount').value;$('#split-diff').textContent='Вся сумма с одного счёта';}else{$('#split-diff').textContent='Разница: '+money(n-sum([...sheet.querySelectorAll('.split-row input')].map(el=>D.cents(el.value||'0'))));}}catch{$('#split-diff').textContent='Проверьте суммы';}}
function recurringForm(id){if(!active().length)return accountForm();const r=state.recurring.find(x=>x.id===id)||{name:'',amount:0,day:1,accountId:active()[0].id,categoryId:state.categories[0].id,before:1};modal(id?'Изменить платёж':'Регулярный платёж',field('Название','name',r.name,'text','required maxlength="80"')+field('Сумма в валюте счёта','amount',r.amount?val(r.amount):'','text','inputmode="decimal" required')+field('День месяца','day',r.day,'number','min="1" max="31" required')+select('Счёт','accountId',aopts([r.accountId]),r.accountId)+select('Категория','categoryId',copts(r.categoryId),r.categoryId)+select('Напоминать за','before',[[0,'В день платежа'],[1,'1 день'],[3,'3 дня'],[7,'7 дней']].map(([n,t])=>[String(n),t]),String(r.before))+'<p class="help">Показываем баннер при открытии. В коротком месяце — последний день. Платёж не списывается автоматически.</p>'+saveButton()+(id?`<button type="button" class="plain danger gap" data-action="deleteRecurring" data-id="${e(id)}">Удалить расписание</button>`:''),async f=>{const amount=D.cents(f.get('amount'));if(amount<=0)throw Error('Сумма должна быть больше нуля');await change(s=>{const item={id:id||D.uid(),name:f.get('name').trim(),amount,day:Number(f.get('day')),accountId:f.get('accountId'),categoryId:f.get('categoryId'),before:Number(f.get('before'))};if(id)s.recurring[s.recurring.findIndex(x=>x.id===id)]=item;else s.recurring.push(item);});close();render();});}
function recurringList(){modal('План платежей',`<div class="row"><button class="primary" data-action="recurringForm">+ Платёж</button><button data-action="ics">В календарь</button></div><p class="help">Оплата отмечается за выбранный месяц. Повторное списание исключено.</p>${monthPicker()}${state.recurring.map(r=>{const paid=!D.unpaid(state,month).some(x=>x.id===r.id);return `<div class="card gap"><div class="row between"><div><strong>${e(r.name)}</strong><div class="help">${D.dueDate(r,month)} · ${money(r.amount,acc(r.accountId).currency)}</div></div><button class="plain small" data-action="recurringForm" data-id="${e(r.id)}">Изменить</button></div><button class="small gap" data-action="pay" data-month="${month}" data-id="${e(r.id)}" ${paid?'disabled':''}>${paid?'Оплачено':'Отметить оплату'}</button></div>`;}).join('')||'<p class="muted gap">Добавьте ипотеку, связь или подписку.</p>'}`);}
function goalsList(){modal('Мои цели',`<button class="primary" data-action="goal">+ Новая цель</button><p class="help">Сумма цели — резерв в рублях. Пополнение не списывает деньги со счетов. Не учитывайте эти же деньги второй раз как отдельный расход.</p>${state.goals.map(g=>`<div class="card gap"><div class="row between"><strong>${e(g.name)}</strong><button class="plain small" data-action="goal" data-id="${e(g.id)}">Изменить</button></div><div class="big gap">${money(g.saved)}</div><div class="progress"><span style="width:${Math.min(100,g.saved/g.target*100)}%"></span></div><p class="help">из ${money(g.target)}</p><button data-action="goalAdd" data-id="${e(g.id)}">Пополнить / снять</button></div>`).join('')}`);}
function goalForm(id){const g=state.goals.find(x=>x.id===id)||{name:'',target:0,saved:0};modal(id?'Изменить цель':'Новая цель',field('Название','name',g.name,'text','required maxlength="80"')+field('Нужно накопить, ₽','target',g.target?val(g.target):'','text','inputmode="decimal" required')+field('Уже отложено, ₽','saved',val(g.saved),'text','inputmode="decimal" required')+saveButton()+(id?`<button class="plain danger gap" type="button" data-action="deleteGoal" data-id="${e(id)}">Удалить цель</button>`:''),async f=>{const target=D.cents(f.get('target')),saved=D.cents(f.get('saved'));if(target<=0||saved<0)throw Error('Проверьте суммы');await change(s=>{const item={id:id||D.uid(),name:f.get('name').trim(),target,saved};if(id)s.goals[s.goals.findIndex(x=>x.id===id)]=item;else s.goals.push(item);});close();render();goalsList();});}
function loanForm(){modal('Добавить долг',field('Имя / название','name','','text','required maxlength="80"')+select('Кто должен','direction',[['owed','Мне должны'],['owe','Я должен']],'owed')+field('Остаток долга, ₽','amount','','text','inputmode="decimal" required')+'<p class="help">Это учёт уже существующего долга, без изменения счетов. Если деньги передали сейчас, отдельно внесите расход или доход.</p>'+saveButton(),async f=>{const amount=D.cents(f.get('amount'));if(amount<=0)throw Error('Сумма должна быть больше нуля');await change(s=>s.loans.push({id:D.uid(),name:f.get('name').trim(),direction:f.get('direction'),remaining:amount,original:amount,date:D.today()}));close();render();loansList();});}
function loansList(){modal('Долги',`<button class="primary" data-action="loan">+ Добавить долг</button><p class="help">Рублёвые долги. Общий чек можно разделить при добавлении расхода.</p>${state.loans.map(l=>`<div class="card gap"><div class="row between"><strong>${e(l.name)}</strong><span class="pill">${l.direction==='owed'?'Мне должны':'Я должен'}</span></div><div class="big gap">${money(l.remaining)}</div><div class="row gap">${l.remaining?`<button data-action="repay" data-id="${e(l.id)}">Возврат</button>`:'<span class="positive">Погашен</span>'}<button class="plain danger" data-action="deleteLoan" data-id="${e(l.id)}">Удалить</button></div></div>`).join('')}`);}
function repayForm(id){const l=state.loans.find(x=>x.id===id),accounts=active().filter(a=>a.currency==='RUB');if(!accounts.length){toast('Создайте рублёвый счёт для возврата');return;}modal('Возврат: '+l.name,field('Сумма, ₽','amount',val(l.remaining),'text','inputmode="decimal" required')+select(l.direction==='owed'?'Зачислить на счёт':'Списать со счёта','accountId',accounts.map(a=>[a.id,a.name]),accounts[0].id)+field('Дата','date',D.today(),'date','required')+saveButton('Подтвердить возврат'),async f=>{const n=D.cents(f.get('amount'));if(n<=0||n>l.remaining)throw Error('Сумма больше остатка долга или равна нулю');await change(s=>{s.loans.find(x=>x.id===id).remaining-=n;s.transactions.push({id:D.uid(),type:l.direction==='owed'?'income':'expense',date:f.get('date'),categoryId:s.categories.find(c=>c.name==='Прочее')?.id||s.categories[0].id,note:'Возврат долга: '+l.name,splits:[{accountId:f.get('accountId'),amount:l.direction==='owed'?n:-n}],loanId:id,created:new Date().toISOString()});});close();render();loansList();});}
