function categoryForm(id){const c=cat(id)||{name:'',section:1,hidden:false};modal(id?'Изменить категорию':'Новая категория',field('Название','name',c.name,'text','required maxlength="60"')+select('Раздел бюджета','section',D.sections.map((n,i)=>[String(i),n]),String(c.section))+`<label><input name="hidden" type="checkbox" ${c.hidden?'checked':''}> Скрыть из новых операций</label><p class="help">Изменение названия и раздела применяется и к истории.</p>`+saveButton(),async f=>{await change(s=>{const item={...c,id:id||D.uid(),name:f.get('name').trim(),section:Number(f.get('section')),hidden:f.has('hidden'),icon:c.icon||'dots'};if(id)s.categories[s.categories.findIndex(x=>x.id===id)]=item;else s.categories.push(item);});close();render();categoriesList();});}
function settings(){const s=state.settings;modal('Настройки',`<form id="settings-form"><h3>Оформление</h3><label class="switch-row"><span>Тёмная тема</span><input type="checkbox" role="switch" id="theme-toggle" ${s.theme==='dark'?'checked':''}></label><label class="switch-row"><span>Как на устройстве</span><input type="checkbox" id="theme-system" ${s.theme==='system'?'checked':''}></label><p class="help">Оформление применяется сразу и сохраняется после закрытия приложения.</p><h3 class="gap">Курсы валют → рубли</h3><p class="help">Курсы пересчитывают сводный баланс, но не изменяют исходные операции. Онлайн-источник — публичное зеркало данных ЦБ РФ.</p><div class="form-row">${field('1 USD = ₽','USD',s.rates.USD,'number','step="0.0001" min="0.0001" max="1000000" required')}${field('1 EUR = ₽','EUR',s.rates.EUR,'number','step="0.0001" min="0.0001" max="1000000" required')}</div><p class="help" id="rate-info">${s.rateSource?e(s.rateSource)+' · ': 'Ручные курсы · '}${e(s.rateOfficialDate||s.ratesDate||'Дата не установлена')}${s.rateFetchedAt?' · загружено '+e(new Date(s.rateFetchedAt).toLocaleString('ru-RU')):''}</p><button class="secondary-action" type="button" id="update-rates">↻ Получить курсы из интернета</button><button class="primary gap" type="submit">Сохранить настройки</button></form><div class="section-head"><h3>Защита и данные</h3></div><label for="reminder-select">Напоминание о резервной копии</label><select id="reminder-select"><option value="7" ${(s.backupReminderDays??7)===7?'selected':''}>Раз в неделю</option><option value="30" ${s.backupReminderDays===30?'selected':''}>Раз в месяц</option><option value="0" ${s.backupReminderDays===0?'selected':''}>Отключено</option></select><div class="list gap">${[['pin',s.pin?'Изменить / убрать PIN':'Установить PIN'],['backup','Сохранить JSON-копию'],['secureBackup','Зашифрованная резервная копия'],['checkBackup','Проверить резервную копию'],['exportCSV','Экспорт операций CSV'],['import','Импорт / восстановление'],['shortcuts','Как установить и настроить Команды']].map(([act,title])=>`<button class="list-item" data-action="${act}"><span class="grow">${title}</span>${icon('chevron')}</button>`).join('')}${s.pin?'<button class="list-item" data-action="lock">Заблокировать сейчас</button>':''}</div><p class="help">PIN ограничивает доступ к экрану, но не шифрует IndexedDB. Зашифрованная резервная копия защищается отдельным паролем. На iOS сохранение файла необходимо завершить вручную.</p>`);
 const toggle=$('#theme-toggle'),sys=$('#theme-system');async function applyTheme(){try{await change(s=>s.settings.theme=sys.checked?'system':toggle.checked?'dark':'light');theme();if(!sys.checked)toggle.disabled=false;toast('Тема изменена');}catch(err){toast(err.message);}}toggle.disabled=sys.checked;toggle.onchange=applyTheme;sys.onchange=()=>{toggle.disabled=sys.checked;applyTheme();};
 $('#reminder-select').onchange=async ev=>{try{await change(s=>s.settings.backupReminderDays=Number(ev.target.value));toast('Напоминание обновлено');}catch(err){toast(err.message);}};
 $('#update-rates').onclick=async()=>{const button=$('#update-rates');button.disabled=true;button.textContent='Загружаем…';try{const data=await fetchCBR(AbortSignal.timeout(12000));await change(s=>{s.settings.rates=data.rates;s.settings.ratesDate=D.today();s.settings.rateOfficialDate=data.rateDate;s.settings.rateFetchedAt=data.fetchedAt;s.settings.rateSource=data.source;});$('#settings-form [name=USD]').value=data.rates.USD;$('#settings-form [name=EUR]').value=data.rates.EUR;$('#rate-info').textContent=data.source+' · курс от '+data.rateDate+' · загружено '+new Date(data.fetchedAt).toLocaleString('ru-RU');render();toast('Курсы обновлены');}catch(err){toast('Курсы не обновлены: '+err.message+'. Доступен ручной ввод.');}finally{button.disabled=false;button.textContent='↻ Получить курсы из интернета';}};
 $('#settings-form').onsubmit=async ev=>{ev.preventDefault();try{const f=new FormData(ev.target);await change(s=>{const usd=Number(f.get('USD')),eur=Number(f.get('EUR'));if(!Number.isFinite(usd)||!Number.isFinite(eur)||usd<=0||eur<=0||usd>1e6||eur>1e6)throw Error('Проверьте курсы');const changed=usd!==s.settings.rates.USD||eur!==s.settings.rates.EUR;s.settings.rates={RUB:1,USD:usd,EUR:eur};if(changed){s.settings.ratesDate=D.today();s.settings.rateSource='Ручной ввод';s.settings.rateOfficialDate=null;s.settings.rateFetchedAt=null;}});close();render();toast('Настройки сохранены');}catch(err){toast(err.message);}};}
async function hashPin(pin,salt){if(!crypto.subtle)throw Error('Для PIN откройте приложение по HTTPS (GitHub Pages)');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits)).map(n=>n.toString(16).padStart(2,'0')).join('');}
function pinForm(){modal('PIN-код',`${state.settings.pin?field('Текущий PIN','current','','password','inputmode="numeric" pattern="[0-9]{4,6}" required autocomplete="off"'):''}${field('Новый PIN: 4–6 цифр','pin','','password','inputmode="numeric" pattern="[0-9]{4,6}" autocomplete="off"')}${field('Повторите новый PIN','repeat','','password','inputmode="numeric" pattern="[0-9]{4,6}" autocomplete="off"')}<p class="help">${state.settings.pin?'Оставьте новый PIN пустым, чтобы отключить блокировку.':'Запомните PIN. Для восстановления доступа понадобится сохранённая копия.'}</p>${saveButton()}`,async f=>{if(state.settings.pin&&await hashPin(f.get('current'),state.settings.pin.salt)!==state.settings.pin.hash)throw Error('Текущий PIN неверный');const pin=f.get('pin');if(pin!==f.get('repeat'))throw Error('Коды не совпадают');if(pin&&!/^\d{4,6}$/.test(pin))throw Error('Нужно 4–6 цифр');const salt=D.uid(),value=pin?{salt,hash:await hashPin(pin,salt)}:null;await change(s=>s.settings.pin=value);close();render();toast(value?'PIN установлен':'PIN отключён');});}
let failures=0,waitUntil=0;
function renderLock(){app.innerHTML=`<main class="container"><form id="unlock" class="lock"><div style="margin:auto">${icon('shield')}</div><h1 class="gap">Stack закрыт</h1><p class="muted">Введите PIN-код</p><input name="pin" aria-label="PIN" type="password" inputmode="numeric" pattern="[0-9]{4,6}" maxlength="6" autocomplete="off" required><button class="primary">Открыть</button><p id="lock-error" class="error" role="alert"></p><p class="help">Код защищает экран этого приложения.</p></form></main>`;$('#unlock').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{if(Date.now()<waitUntil)throw Error('Подождите 30 секунд перед следующей попыткой');if(await hashPin(new FormData(ev.target).get('pin'),state.settings.pin.salt)!==state.settings.pin.hash){failures++;if(failures>=5){waitUntil=Date.now()+30000;failures=0;}throw Error('Неверный PIN');}failures=0;locked=false;lastActivity=Date.now();render();consumeURL();}catch(err){$('#lock-error').textContent=err.message;}finally{b.disabled=false;}};}
function lock(){if(!state.settings.pin)return;close();locked=true;render();}
async function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function backup(){const out=backupSnapshot(state);const date=new Date().toISOString();out.settings.lastBackup=date;backupSummary(out);await download(JSON.stringify(out,null,2),`Stack-backup-${D.today()}.json`);await change(s=>s.settings.lastBackup=date);render();toast('Файл подготовлен. Убедитесь, что он сохранён в «Файлы».');}
async function secureBackup(){modal('Зашифрованная копия',`<p class="muted">Шифрование AES-256-GCM. Запомните пароль: восстановить его будет невозможно.</p>${field('Пароль (минимум 10 символов)','password','','password','required minlength="10" autocomplete="new-password"')}${field('Повторить пароль','repeat','','password','required minlength="10" autocomplete="new-password"')}${saveButton('Подготовить защищённый файл')}`,async f=>{if(f.get('password')!==f.get('repeat'))throw Error('Пароли не совпадают');const out=backupSnapshot(state),encrypted=await encryptBackup(out,f.get('password'));await download(JSON.stringify(encrypted),`Stack-secure-${D.today()}.stack.json`);await change(s=>s.settings.lastBackup=new Date().toISOString());close();render();toast('Зашифрованный файл подготовлен. Проверьте его в «Файлы».');});}
function checkBackup(){modal('Проверка копии',`<p class="muted">Можно проверить JSON или зашифрованную копию без изменения текущих данных.</p><input id="verify-file" type="file" accept=".json,.stack,application/json"><div id="verify-result" class="help" role="status"></div>`);$('#verify-file').onchange=async ev=>{const target=$('#verify-result');try{const file=ev.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Файл слишком большой');let data=JSON.parse(await file.text());if(data.format==='stack-encrypted'){const password=prompt('Введите пароль копии');if(password===null)return;data=await decryptBackup(data,password);}const info=backupSummary(data);target.textContent=`✓ Копия корректна: ${info.accounts} счетов, ${info.transactions} операций, ${info.categories} категорий. Текущие данные не изменены.`;}catch(err){target.textContent='Ошибка проверки: '+err.message;}};}
function exportCSV(){const q=x=>'"'+String(x??'').replaceAll('"','""')+'"';const rows=[['date','type','amount','currency','account','category','note','transaction_id']];for(const t of state.transactions.filter(t=>!t.deleted))for(const p of t.splits)rows.push([t.date,t.type,val(p.amount),acc(p.accountId).currency,acc(p.accountId).name,cat(t.categoryId)?.name||'',t.note,t.id]);download('\uFEFF'+rows.map(r=>r.map(q).join(';')).join('\r\n'),'Stack-operations.csv','text/csv;charset=utf-8');toast('Для полного восстановления используйте JSON, а не CSV.');}
function importDialog(){modal('Импорт данных',`<p class="muted">JSON-копия Stack восстанавливает всю базу. Money Radar и CSV добавляют операции на выбранный счёт после проверки.</p><label for="import-file">Выберите JSON или CSV</label><input type="file" id="import-file" accept=".json,.stack,.csv,text/csv,application/json"><p id="import-error" class="error" role="alert"></p><p class="help">Поддерживается CSV с колонками date (или Дата), amount (или Сумма), type, note. Без type: минус — расход, плюс — доход. Банковские форматы отличаются: пример есть в архиве. Перед восстановлением сохраните текущую JSON-копию.</p>`);$('#import-file').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Максимальный размер — 20 МБ');const text=await file.text();if(file.name.toLowerCase().endsWith('.json')){const parsed=JSON.parse(text);if(parsed.format==='stack-encrypted'){const password=prompt('Введите пароль защищённой копии');if(password===null)return;pendingImport=await decryptBackup(parsed,password);importKind='stack';restorePreview();return;}if(parsed.format==='stack'){D.validateBackup(parsed);pendingImport=parsed;importKind='stack';restorePreview();return;}pendingImport=D.legacyCandidates(parsed);importKind='money';}else{pendingImport=D.csvCandidates(text);importKind='csv';}if(!active().length)throw Error('Сначала создайте счёт для импорта операций');importPreview();}catch(err){if($('#import-error'))$('#import-error').textContent=err.message;else toast(err.message);}};}
function restorePreview(){modal('Восстановление Stack',`<div class="card"><strong>${pendingImport.accounts.length} счетов · ${pendingImport.transactions.filter(t=>!t.deleted).length} операций</strong><p class="help">Текущая база будет заменена целиком. PIN из файла не переносится. Текущий PIN этого устройства сохраняется.</p></div><button type="button" class="gap" data-action="backup">Сначала сохранить текущую копию</button><label><input type="checkbox" name="confirm" required> Заменить текущие данные этой копией</label>${saveButton('Восстановить')}`,async()=>{const next=structuredClone(pendingImport),pin=state.settings.pin;await change(s=>{const revision=s.revision;Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,next,{revision});s.settings.pin=pin;s.transactions.forEach(t=>{t.created=t.created||new Date().toISOString();});});pendingImport=null;close();render();toast('Резервная копия восстановлена');});}
function importPreview(){const items=pendingImport;modal('Проверка импорта',`<p><strong>${items.length} операций</strong> · ${importKind==='money'?'Money Radar':'CSV'}</p>${select('На счёт (суммы в его валюте)','accountId',aopts(),active()[0]?.id)}${select('Категория по умолчанию','categoryId',copts(),state.categories.find(c=>c.name==='Прочее')?.id)}<p class="help">Будут пропущены совпадения по дате, типу, сумме, счёту и заметке. Старые категории Money Radar сопоставляются по имени.</p><div class="list gap">${items.slice(0,8).map(t=>`<div class="list-item"><span class="grow"><strong>${e(t.note||t.categoryName||t.type)}</strong><small>${t.date}</small></span><strong>${t.type==='expense'?'−':'+'}${(t.amount/100).toLocaleString('ru-RU')}</strong></div>`).join('')}</div>${items.length>8?'<p class="help">Показаны первые 8 записей.</p>':''}${saveButton('Добавить операции')}`,async f=>{const accountId=f.get('accountId');let added=0,skipped=0;await change(s=>{for(const item of items){const p={accountId,amount:item.type==='expense'?-item.amount:item.amount};if(s.transactions.some(t=>!t.deleted&&t.date===item.date&&t.type===item.type&&(t.note||'')===(item.note||'')&&t.splits.length===1&&t.splits[0].accountId===accountId&&t.splits[0].amount===p.amount)){skipped++;continue;}s.transactions.push({id:D.uid(),date:item.date,type:item.type,note:item.note||'',categoryId:s.categories.find(c=>c.name.toLowerCase()===item.categoryName?.toLowerCase())?.id||f.get('categoryId'),splits:[p],created:new Date().toISOString()});added++;}});pendingImport=null;close();render();toast(`Добавлено: ${added}, совпадений пропущено: ${skipped}`);});}
let currentRecognition=null;
function voiceForm(){modal('Голосовая операция',`<p class="muted">Произнесите операцию и проверьте сумму перед сохранением. Распознавание в некоторых браузерах использует сторонние сервисы.</p><button type="button" id="voice-start" class="primary">🎙 Начать запись</button><button type="button" id="voice-stop" class="secondary-action" disabled>Остановить</button><p id="voice-status" class="help" role="status">${recognitionAvailable()?'Нажмите «Начать запись»':'Распознавание недоступно. Нажмите поле ниже и используйте микрофон клавиатуры iPhone.'}</p><label for="voice-text">Распознанный текст (можно редактировать)</label><textarea id="voice-text" placeholder="Например: потратил 750 рублей на продукты"></textarea><button type="button" id="voice-parse" class="primary gap">Проверить операцию</button>`);
 const status=$('#voice-status'),start=$('#voice-start'),stop=$('#voice-stop');if(!recognitionAvailable())start.disabled=true;
 function stopVoice(){try{currentRecognition?.stop();}catch{}currentRecognition=null;stop.disabled=true;start.disabled=!recognitionAvailable();}
 start.onclick=()=>{try{status.textContent='Слушаю…';start.disabled=true;stop.disabled=false;currentRecognition=startRecognition({onResult:text=>{$('#voice-text').value=text;status.textContent='Распознано. Проверьте текст.';},onError:err=>{status.textContent=err;},onEnd:()=>{stopVoice();}});}catch(err){stopVoice();status.textContent=err.message;}};
 stop.onclick=stopVoice;$('#voice-parse').onclick=()=>{const text=$('#voice-text').value.trim();if(!text){status.textContent='Введите или произнесите текст операции';return;}stopVoice();smartForm(text);};
}
function smartForm(text=''){modal('Из текста или QR чека',`<label for="smart-text">SMS, текст траты или содержимое QR</label><textarea id="smart-text" name="text" required placeholder="Покупка 450,50 RUB. Кафе. Остаток 12 000 RUB">${e(text)}</textarea><p class="help">Вставьте текст SMS вручную. Для QR используйте системный сканер / Команды и вставьте строку вида t=20261030T1444&s=450.50&fn=… Сумма и дата откроются для проверки.</p>${saveButton('Разобрать текст')}`,f=>{const parsed=D.parseText(f.get('text')),keywords=[[/кафе|coffee|кофе|ресторан/i,'Кафе'],[/пятероч|пятёроч|магнит|продукт|супермаркет/i,'Продукты'],[/такси|taxi|транспорт|бензин/i,'Транспорт'],[/зарплат/i,'Зарплата']];const guess=keywords.find(([re])=>re.test(parsed.note));parsed.categoryId=state.categories.find(c=>c.name===guess?.[1])?.id||state.categories.find(c=>c.name==='Прочее')?.id;txForm(undefined,parsed);});}
function shortcuts(){const base=location.href.split('#')[0].split('?')[0];modal('Установка и Команды',`<h3>На iPhone</h3><p class="muted">Откройте страницу в Safari → «Поделиться» → «На экран Домой». Запустите с иконки и один раз дождитесь сообщения «Готово к работе офлайн».</p><h3>На Android</h3><p class="muted">В меню Chrome выберите «Установить приложение» или «Добавить на главный экран».</p><h3>Быстрый ввод из Команд</h3><p class="muted">В приложении «Команды»: «Запросить ввод» (текст) → «Кодировать URL» → «Текст» (ссылка ниже + закодированный ввод) → «Открыть URL».</p><div class="code">${e(base)}#text=ЗАКОДИРОВАННЫЙ_ТЕКСТ</div><p class="help">Текст после # не передаётся серверу GitHub. После разбора ссылка очищается. Операция всегда требует подтверждения. Для отдельной суммы: #add=1&amount=450.50&type=expense&note=Кофе</p><p class="help">Команды могут открывать Safari отдельно от установленного PWA. Проверьте, что видите свои счета перед сохранением. Если хранилища различаются, вставляйте текст внутри Stack.</p><h3>Голос и чеки</h3><p class="muted">При желании замените запрос текста действием «Диктовать текст» или сканированием QR в Командах. Обработка голоса зависит от настроек iOS и может использовать сеть. Сам Stack не записывает звук и не отправляет текст на распознавание.</p><button class="primary" data-action="smart">Открыть умный ввод</button>`);}
function consumeURL(){if(locked||!state.accounts.length||!pendingURL)return;const input=pendingURL;pendingURL='';window.history.replaceState(null,'',location.pathname+location.search);const q=new URLSearchParams(input);try{if(q.has('text'))smartForm(q.get('text').slice(0,5000));else if(q.has('add')){const n=D.cents(q.get('amount')||'0');if(n<=0)throw Error('В ссылке отсутствует сумма');txForm(undefined,{amount:n,type:q.get('type')==='income'?'income':'expense',note:(q.get('note')||'').slice(0,500)});}}catch(err){toast(err.message);}}
window.addEventListener('hashchange',()=>{pendingURL=location.hash.slice(1);consumeURL();});
function confirmAction(title,text,fn){modal(title,`<p class="muted">${e(text)}</p><button type="submit" class="primary">Подтвердить</button>`,async()=>{await fn();close();render();});}
async function deleteTx(id){const t=state.transactions.find(t=>t.id===id);if(t.loanId){toast('Возврат долга нельзя редактировать. Удаление восстановит остаток долга.');}const linked=state.loans.find(l=>l.transactionId===id);if(linked){toast('Сначала удалите связанную запись долга в разделе «Долги».');return;}await change(s=>{s.transactions.find(t=>t.id===id).deleted=true;if(t.loanId){const l=s.loans.find(l=>l.id===t.loanId);if(l)l.remaining+=D.amount(t);}});close();render();toast('Операция удалена',async()=>{try{await change(s=>{s.transactions.find(t=>t.id===id).deleted=false;if(t.loanId){const l=s.loans.find(l=>l.id===t.loanId);if(l){if(l.remaining<D.amount(t))throw Error('Долг уже изменён');l.remaining-=D.amount(t);}}});render();toast('Удаление отменено');}catch(err){toast(err.message);}});}
const actions={
 settings,account:accountForm,budgets:budgetForm,addTx:()=>txForm(),transfer:()=>{if(active().length<2){toast('Создайте второй счёт для перевода');return;}txForm(undefined,{type:'transfer'});},editTx:id=>{const t=state.transactions.find(t=>t.id===id);if(state.loans.some(l=>l.transactionId===id)){modal('Общий чек',`<p>${e(t.note||cat(t.categoryId)?.name)}</p><p class="big">${money(D.amount(t))}</p><p class="help">К этому чеку привязан долг. Чтобы изменить или удалить чек, сначала удалите связанную запись долга и при необходимости создайте её заново с правильным остатком. Денежные операции возврата сохранятся.</p><button data-action="loans">Открыть долги</button>`);return;}if(t.loanId){modal('Возврат долга',`<p>${e(t.note)}</p><p class="big">${money(D.amount(t))}</p><p class="help">Чтобы изменить возврат, удалите его и внесите заново. Остаток долга восстановится.</p><button class="danger" data-action="deleteTx" data-id="${e(id)}">Удалить возврат</button>`);return;}txForm(id);},deleteTx,
 archive:async id=>{const a=acc(id);if(!a.archived){if(active().length===1)throw Error('Нужен хотя бы один активный счёт');if(state.recurring.some(r=>r.accountId===id)||state.templates.some(t=>t.accountId===id))throw Error('Сначала перенесите шаблоны и платежи на другой счёт');}await change(s=>s.accounts.find(a=>a.id===id).archived=!a.archived);close();render();},
 accounts:()=>modal('Все счета',`<button class="primary" data-action="account">+ Новый счёт</button><div class="list gap">${state.accounts.map(a=>`<button class="list-item" data-action="account" data-id="${e(a.id)}"><span class="grow">${e(a.name)}${a.archived?' · архив':''}</span><strong>${money(D.balance(state,a.id),a.currency)}</strong></button>`).join('')}</div>`),
 addSplit:()=>{captureSplits();const a=active().find(a=>!splitDraft.some(p=>p.accountId===a.id)&&a.currency===acc(splitDraft[0].accountId).currency);if(!a)throw Error('Нужен ещё один счёт в той же валюте');splitDraft.push({accountId:a.id,value:''});renderSplits();},equalSplit:()=>{captureSplits();const n=D.cents($('#f-amount').value),v=Math.floor(n/splitDraft.length);splitDraft.forEach((p,i)=>p.value=val(v+(i===0?n-v*splitDraft.length:0)));renderSplits();},
 moreHistory:()=>{limit+=60;render();},recurring:recurringList,recurringForm,
 pay:(id,button)=>{const r=state.recurring.find(r=>r.id===id),m=button?.dataset.month||monthNow();if(!D.unpaid(state,m).some(r=>r.id===id))throw Error('Этот платёж уже оплачен');modal('Оплата: '+r.name,`<p class="big">${money(r.amount,acc(r.accountId).currency)}</p><p class="muted">Со счёта ${e(acc(r.accountId).name)} · за ${m}</p>${field('Фактическая дата оплаты','date',D.today(),'date','required')}${saveButton('Подтвердить оплату')}`,async f=>{await change(s=>{if(!D.unpaid(s,m).some(r=>r.id===id))throw Error('Уже оплачено');s.transactions.push({id:D.uid(),type:'expense',date:f.get('date'),categoryId:r.categoryId,note:r.name,splits:[{accountId:r.accountId,amount:-r.amount}],recurringId:r.id,recurringMonth:m,created:new Date().toISOString()});});close();render();toast('Платёж записан');});},
 ics:()=>{if(!state.recurring.length)throw Error('Сначала добавьте платёж');download(D.ics(state),'Stack-payments.ics','text/calendar;charset=utf-8');toast('Откройте файл в календаре и подтвердите импорт');},
 deleteRecurring:id=>confirmAction('Удалить расписание?','История оплаченных операций сохранится.',()=>change(s=>s.recurring=s.recurring.filter(r=>r.id!==id))),
 goals:goalsList,goal:goalForm,goalAdd:id=>{const g=state.goals.find(g=>g.id===id);modal('Резерв: '+g.name,field('Сумма, ₽ (минус — снять из резерва)','amount','','text','inputmode="decimal" required')+saveButton(),async f=>{const n=D.cents(f.get('amount'));if(g.saved+n<0)throw Error('В резерве недостаточно денег');await change(s=>s.goals.find(g=>g.id===id).saved+=n);close();render();goalsList();});},deleteGoal:id=>confirmAction('Удалить цель?','Резерв освободится. Балансы счетов не изменятся.',()=>change(s=>s.goals=s.goals.filter(g=>g.id!==id))),
 loans:loansList,loan:loanForm,repay:repayForm,deleteLoan:id=>confirmAction('Удалить запись долга?','История денежных операций сохранится; остаток долга больше не будет отслеживаться.',()=>change(s=>{s.loans=s.loans.filter(l=>l.id!==id);s.transactions.forEach(t=>{if(t.loanId===id)delete t.loanId;});})),
 template:templateForm,useTemplate:id=>{const t=state.templates.find(t=>t.id===id);txForm(undefined,{amount:t.amount,categoryId:t.categoryId,accountId:t.accountId,note:t.name});},templates:()=>modal('Шаблоны',`<button class="primary" data-action="template">+ Шаблон</button><div class="list gap">${state.templates.map(t=>`<button class="list-item" data-action="template" data-id="${e(t.id)}"><span class="grow">${e(t.name)}</span><strong>${money(t.amount,acc(t.accountId).currency)}</strong></button>`).join('')}</div>`),deleteTemplate:id=>confirmAction('Удалить шаблон?','Операции, созданные по шаблону, сохранятся.',()=>change(s=>s.templates=s.templates.filter(t=>t.id!==id))),
 categories:categoriesList,category:categoryForm,backup,secureBackup,checkBackup,exportCSV,import:importDialog,smart:()=>smartForm(),voice:voiceForm,shortcuts,pin:pinForm,lock
};
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-close')){close();return;}if(locked)return;if(b.dataset.nav){close();if(b.dataset.nav==='add')txForm();else{view=b.dataset.nav;limit=60;render();window.scrollTo({top:0,behavior:'instant'});}return;}if(b.dataset.removeSplit!==undefined){captureSplits();splitDraft.splice(Number(b.dataset.removeSplit),1);renderSplits();return;}const act=b.dataset.action;if(actions[act])await actions[act](b.dataset.id,b);}catch(err){toast(err.message);}});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){const start=ev.target.selectionStart;search=ev.target.value;render();$('#search').focus();$('#search').setSelectionRange(start,start);}if(ev.target.id==='f-amount'&&$('#splits'))splitDiff();if(ev.target.closest('.split-row'))splitDiff();});
document.addEventListener('change',ev=>{if(ev.target.id==='month'){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(ev.target.value))return;month=ev.target.value;if(sheet.open)recurringList();else render();}if(ev.target.id==='account-filter'){filter=ev.target.value;render();}});
['pointerdown','keydown'].forEach(type=>document.addEventListener(type,()=>lastActivity=Date.now(),{passive:true}));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state?.settings.pin)lock();else if(!document.hidden&&state&&!locked)render();});
setInterval(()=>{if(state?.settings.pin&&!locked&&Date.now()-lastActivity>120000)lock();},15000);
try{state=await openDB();D.validateBackup(state);state.transactions.forEach(t=>t.created=t.created||'');locked=!!state.settings.pin;render();consumeURL();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(reg=>{const announce=()=>toast('Доступно обновление. Закройте все окна Stack и откройте снова.');if(reg.waiting)announce();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting&&navigator.serviceWorker.controller)announce();});});return navigator.serviceWorker.ready;}).then(()=>{if(!locked)toast('Готово к работе офлайн');}).catch(()=>toast('Офлайн-кэш не установлен. Проверьте HTTPS и файлы на GitHub.'));}if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}catch(err){app.innerHTML=`<main class="container"><h1>Не удалось открыть Stack</h1><p>${e(err.message)}</p><p class="muted">Не очищайте данные браузера. Проверьте обычный режим Safari/Chrome, свободную память и HTTPS, затем перезагрузите страницу.</p></main>`;}
